// All file access for the log goes through a FileOps object so that it can be
// swapped for the power-loss model described in docs/crash-testing.md.
//
// Operations are path based, so no handle stays open between calls.

import fs from 'node:fs';
import path from 'node:path';

const NO_DIR_SYNC = new Set(['EPERM', 'EISDIR', 'EINVAL', 'EBADF', 'EACCES']);

class RealFileOps {
  exists(file) {
    return fs.existsSync(file);
  }

  size(file) {
    return fs.statSync(file).size;
  }

  /** Reads from `offset` to `offset + length`, or to end of file. */
  read(file, offset = 0, length = Infinity) {
    const fd = fs.openSync(file, 'r');
    try {
      const available = Math.max(0, fs.fstatSync(fd).size - offset);
      const buffer = Buffer.allocUnsafe(Math.min(available, length));
      let filled = 0;
      while (filled < buffer.length) {
        const n = fs.readSync(fd, buffer, filled, buffer.length - filled, offset + filled);
        if (n === 0) break;
        filled += n;
      }
      return buffer.subarray(0, filled);
    } finally {
      fs.closeSync(fd);
    }
  }

  create(file, { exclusive = false } = {}) {
    fs.closeSync(fs.openSync(file, exclusive ? 'wx' : 'w'));
  }

  writeAt(file, bytes, position) {
    const fd = fs.openSync(file, 'r+');
    try {
      let written = 0;
      while (written < bytes.length) {
        written += fs.writeSync(fd, bytes, written, bytes.length - written, position + written);
      }
    } finally {
      fs.closeSync(fd);
    }
  }

  sync(file) {
    const fd = fs.openSync(file, 'r+');
    try {
      fs.fsyncSync(fd);
    } finally {
      fs.closeSync(fd);
    }
  }

  truncate(file, length) {
    const fd = fs.openSync(file, 'r+');
    try {
      fs.ftruncateSync(fd, length);
      fs.fsyncSync(fd);
    } finally {
      fs.closeSync(fd);
    }
  }

  rename(from, to) {
    fs.renameSync(from, to);
  }

  unlink(file) {
    fs.rmSync(file, { force: true });
  }

  /** Not every platform can sync a directory; those that cannot refuse with an error. */
  syncDir(dir) {
    let fd;
    try {
      fd = fs.openSync(dir, 'r');
      fs.fsyncSync(fd);
    } catch (err) {
      if (!NO_DIR_SYNC.has(err.code)) throw err;
    } finally {
      if (fd !== undefined) fs.closeSync(fd);
    }
  }
}

// Keeps written bytes in this process until sync(), like a page cache. A process
// killed at a failpoint therefore loses them, as a machine losing power would.
class PowerLossFileOps extends RealFileOps {
  constructor() {
    super();
    this.pending = new Map();
  }

  size(file) {
    let size = super.size(file);
    for (const { position, bytes } of this.pending.get(file) ?? []) {
      size = Math.max(size, position + bytes.length);
    }
    return size;
  }

  read(file, offset = 0, length = Infinity) {
    const writes = this.pending.get(file);
    if (!writes?.length) return super.read(file, offset, length);
    const image = Buffer.alloc(this.size(file));
    super.read(file).copy(image);
    for (const { position, bytes } of writes) bytes.copy(image, position);
    return image.subarray(offset, Math.min(image.length, offset + length));
  }

  create(file, options) {
    super.create(file, options);
    this.pending.delete(file);
  }

  writeAt(file, bytes, position) {
    if (!this.pending.has(file)) this.pending.set(file, []);
    this.pending.get(file).push({ position, bytes: Buffer.from(bytes) });
  }

  sync(file) {
    for (const { position, bytes } of this.pending.get(file) ?? []) {
      super.writeAt(file, bytes, position);
    }
    this.pending.delete(file);
    super.sync(file);
  }

  truncate(file, length) {
    super.truncate(file, length);
    const kept = (this.pending.get(file) ?? []).filter((w) => w.position + w.bytes.length <= length);
    this.pending.set(file, kept);
  }

  rename(from, to) {
    super.rename(from, to);
    const moving = this.pending.get(from);
    this.pending.delete(from);
    if (moving) this.pending.set(to, moving);
    else this.pending.delete(to);
  }

  unlink(file) {
    super.unlink(file);
    this.pending.delete(file);
  }
}

export function createFileOps() {
  return process.env.WALQ_SIMULATE_POWER_LOSS === '1' ? new PowerLossFileOps() : new RealFileOps();
}

export function ensureDir(dir) {
  fs.mkdirSync(path.resolve(dir), { recursive: true });
}

##### lock
// Cross-process mutex. The lock is an exclusive-share handle on queue.lock, so
// the operating system drops it the moment the holder dies, however it dies.
// There is no stale-lock cleanup to get wrong.

import fs from 'node:fs';
import { sleepSync } from './clock.mjs';
import { LockTimeoutError } from './errors.mjs';

// libuv's UV_FS_O_EXLOCK: open with no sharing on Windows, O_EXLOCK on macOS.
const O_EXLOCK = 0x10000000;
const OPEN_FLAGS = fs.constants.O_CREAT | fs.constants.O_RDWR | O_EXLOCK;
const BUSY = new Set(['EBUSY', 'EPERM', 'EACCES', 'EAGAIN', 'EWOULDBLOCK']);

if (process.platform !== 'win32' && process.platform !== 'darwin') {
  throw new Error('walq needs exclusive-open locks, which this platform does not provide');
}

/** Blocks until the lock is held and returns the function that releases it. */
export function acquireLock(lockPath, { timeoutMs }) {
  const deadline = performance.now() + timeoutMs;
  let wait = 0.5;
  for (;;) {
    try {
      const fd = fs.openSync(lockPath, OPEN_FLAGS);
      return () => fs.closeSync(fd);
    } catch (err) {
      if (!BUSY.has(err.code)) throw err;
    }
    if (performance.now() >= deadline) throw new LockTimeoutError(lockPath, timeoutMs);
    sleepSync(wait + Math.random() * wait);
    wait = Math.min(wait * 1.5, 6);
  }
}

##### store
// Store: the replayed state plus the rules for reading and writing the log.
// Every read of shared state and every write happens inside withLock(), which
// first brings this process up to date with whatever other processes wrote.

import path from 'node:path';
import { compactLog } from './compactor.mjs';
import { QueueClosedError } from './errors.mjs';
import { FORMAT_VERSION, HEADER_SIZE } from './frame.mjs';
import { createFileOps, ensureDir } from './fsops.mjs';
import { acquireLock } from './lock.mjs';
import { createLogger } from './logger.mjs';
import { applyRecord, createState } from './state.mjs';
import { Wal } from './wal.mjs';

export const WAL_FILE = 'wal.log';
export const LOCK_FILE = 'queue.lock';

const log = createLogger('store');

export class Store {
  constructor(dir, config) {
    this.dir = dir;
    this.config = config;
    this.clock = config.clock;
    this.ops = createFileOps();
    this.wal = new Wal(path.join(dir, WAL_FILE), this.ops);
    this.lockPath = path.join(dir, LOCK_FILE);
    this.state = createState();
    this.generation = null;
    this.offset = HEADER_SIZE;
    this.snapshotBytes = 0;
    this.tornTailsDropped = 0;
    this.lastCompactionError = null;
    this.closed = false;
    this.holdingLock = false;
  }

  open() {
    ensureDir(this.dir);
    this.#locked(() => {
      if (!this.wal.exists()) this.wal.create();
      this.catchUp();
    });
  }

  close() {
    this.closed = true;
  }

  #locked(fn) {
    if (this.holdingLock) throw new Error('queue lock is not reentrant');
    const release = acquireLock(this.lockPath, { timeoutMs: this.config.lockTimeoutMs });
    this.holdingLock = true;
    try {
      return fn();
    } finally {
      this.holdingLock = false;
      release();
    }
  }

  withLock(fn) {
    if (this.closed) throw new QueueClosedError();
    return this.#locked(() => {
      this.catchUp();
      return fn();
    });
  }

  /** Brings this.state up to date with the log without doing anything else. */
  refresh() {
    this.withLock(() => {});
  }

  catchUp() {
    const header = this.wal.readHeader();
    if (this.generation === null || this.ops.size(this.wal.file) < this.offset) {
      this.state = createState();
      this.offset = HEADER_SIZE;
      this.generation = header.generation;
    }

    const { frames, end, tail } = this.wal.scanFrom(this.offset);
    for (const frame of frames) {
      applyRecord(this.state, frame.record, this.clock);
      if (frame.record.t === 'snapshot') this.snapshotBytes = frame.size;
    }
    this.offset = end;

    if (tail) {
      this.tornTailsDropped += 1;
      log.warn('ignored incomplete tail', { offset: end, reason: tail.reason, bytes: tail.bytes });
    }
  }

  /** Must be called inside withLock(). */
  append(records, options) {
    this.offset = this.wal.append(records, options);
    for (const record of records) applyRecord(this.state, record, this.clock);
  }

  /** Must be called inside withLock(). */
  compact() {
    const bytesBefore = this.offset;
    const { snapshot, generation, size } = compactLog({
      wal: this.wal,
      ops: this.ops,
      state: this.state,
      generation: this.generation,
      now: this.clock.now(),
      config: this.config,
    });
    this.state = createState();
    applyRecord(this.state, snapshot);
    this.generation = generation;
    this.offset = size;
    this.snapshotBytes = size - HEADER_SIZE;
    log.info('compacted', { generation, bytesBefore, bytesAfter: size });
    return { generation, bytesBefore, bytesAfter: size, jobs: this.state.jobs.size };
  }

  /**
   * Compacts when the log has outgrown the threshold. A failure here must not
   * fail the operation that triggered it, because that operation has committed.
   */
  maybeCompact() {
    const threshold = this.config.compactAfterBytes;
    if (!threshold) return;
    if (this.offset < threshold) return;
    try {
      this.compact();
      this.lastCompactionError = null;
    } catch (err) {
      this.lastCompactionError = err;
      log.warn('compaction failed', { error: err.message });
    }
  }

  describe() {
    return {
      format: FORMAT_VERSION,
      generation: this.generation,
      logBytes: this.offset,
      tornTailsDropped: this.tornTailsDropped,
      lastCompactionError: this.lastCompactionError?.message ?? null,
    };
  }
}

##### state
// The queue's state is a pure fold over the log. Replaying the same records must
// give the same state in every process, at any time.

import { loadSnapshot } from './snapshot.mjs';

export function createState() {
  return { jobs: new Map(), idem: new Map(), seq: 0, completionSeq: 0 };
}

function requeue(job, availableAt, error) {
  job.status = 'ready';
  job.availableAt = availableAt;
  job.lease = null;
  job.lastError = error ?? job.lastError;
}

export function applyRecord(state, rec, clock) {
  if (rec.t === 'snapshot') {
    loadSnapshot(state, rec);
    return;
  }
  if (rec.t === 'enqueue') {
    state.seq += 1;
    state.jobs.set(rec.id, {
      id: rec.id,
      type: rec.type,
      payload: rec.payload,
      key: rec.key ?? null,
      priority: rec.priority ?? 0,
      status: 'ready',
      attempts: 0,
      fence: 0,
      maxAttempts: rec.maxAttempts,
      availableAt: rec.availableAt,
      lease: null,
      result: null,
      lastError: null,
      enqueuedAt: rec.at,
      completedAt: null,
      completionSeq: null,
      seq: state.seq,
    });
    if (rec.key) state.idem.set(rec.key, { id: rec.id, at: rec.at });
    return;
  }

  const job = state.jobs.get(rec.id);
  if (!job) return;

  switch (rec.t) {
    case 'claim':
      job.status = 'leased';
      job.attempts += 1;
      job.fence = rec.fence;
      job.lease = { worker: rec.worker, fence: rec.fence, until: rec.leaseUntil };
      break;
    case 'heartbeat':
      if (job.lease && job.lease.fence === rec.fence) job.lease.until = rec.leaseUntil;
      break;
    case 'complete':
      state.completionSeq += 1;
      job.status = 'done';
      job.lease = null;
      job.result = rec.result ?? null;
      job.completedAt = rec.at;
      job.completionSeq = state.completionSeq;
      break;
    case 'fail':
    case 'expire':
      requeue(job, clock.now() + rec.delayMs, rec.error);
      break;
    case 'dead':
    case 'cancel':
      job.status = rec.t === 'dead' ? 'dead' : 'cancelled';
      job.lease = null;
      job.lastError = rec.error ?? job.lastError;
      job.completedAt = rec.at;
      break;
    case 'requeue':
      job.attempts = 0;
      job.fence = 0;
      job.completedAt = null;
      requeue(job, rec.at, job.lastError);
      break;
    default:
      // Unknown record types come from a newer writer; ignoring them keeps old
      // tools able to read the rest of the log.
      break;
  }
}

##### records
// Constructors for the records stored in the log. docs/wal-format.md lists them.

export function enqueueRecord({ id, type, payload, key, priority, maxAttempts, availableAt, at }) {
  return { t: 'enqueue', id, type, payload, key: key ?? null, priority: priority ?? 0, maxAttempts, availableAt, at };
}

export function claimRecord({ id, worker, fence, leaseUntil, at }) {
  return { t: 'claim', id, worker, fence, leaseUntil, at };
}

export function heartbeatRecord({ id, fence, leaseUntil, at }) {
  return { t: 'heartbeat', id, fence, leaseUntil, at };
}

export function completeRecord({ id, fence, result, at }) {
  return { t: 'complete', id, fence, result: result ?? null, at };
}

export function failRecord({ id, fence, error, delayMs, at }) {
  return { t: 'fail', id, fence, error, delayMs, at };
}

export function expireRecord({ id, fence, delayMs, at }) {
  return { t: 'expire', id, fence, error: 'lease expired', delayMs, at };
}

export function deadRecord({ id, fence, error, at }) {
  return { t: 'dead', id, fence, error, at };
}

export function cancelRecord({ id, fence, error, at }) {
  return { t: 'cancel', id, fence, error, at };
}

export function requeueRecord({ id, at }) {
  return { t: 'requeue', id, at };
}

##### snapshot
// A compacted log starts with one snapshot record holding the state it replaces.

import { isPastRetention } from './retention.mjs';

function serializeJob(job) {
  return {
    id: job.id,
    type: job.type,
    payload: job.payload,
    key: job.key,
    status: job.status,
    maxAttempts: job.maxAttempts,
    availableAt: job.availableAt,
    lease: job.lease,
    result: job.result,
    lastError: job.lastError,
    enqueuedAt: job.enqueuedAt,
    completedAt: job.completedAt,
    completionSeq: job.completionSeq,
    seq: job.seq,
  };
}

/** Builds the snapshot record, dropping terminal jobs past their retention. */
export function buildSnapshot(state, now, config) {
  const kept = [];
  for (const job of state.jobs.values()) {
    if (!isPastRetention(job, now, config)) kept.push(job);
  }

  return {
    t: 'snapshot',
    at: now,
    seq: state.seq,
    completionSeq: state.completionSeq,
    jobs: kept.map(serializeJob),
  };
}

export function loadSnapshot(state, rec) {
  state.seq = rec.seq;
  state.completionSeq = rec.completionSeq ?? 0;
  state.jobs = new Map();
  state.idem = new Map();
  for (const job of rec.jobs) {
    state.jobs.set(job.id, {
      ...job,
      priority: job.priority ?? 0,
      attempts: job.attempts ?? 0,
      fence: job.fence ?? job.lease?.fence ?? 0,
      completionSeq: job.completionSeq ?? null,
    });
    if (job.key && !state.idem.has(job.key)) {
      state.idem.set(job.key, { id: job.id, at: job.enqueuedAt });
    }
  }
}

##### retention
// How long finished jobs stay in the log.

const TERMINAL = new Set(['done', 'dead']);

export function isTerminal(job) {
  return TERMINAL.has(job.status);
}

export function isPastRetention(job, now, config) {
  return isTerminal(job) && now - job.completedAt >= config.retainCompletedMs;
}

##### compactor
// Replaces the log with a one-record log holding the current state. Runs under
// the queue lock. docs/compaction.md describes the protocol.

import path from 'node:path';
import { encodeFrame, encodeHeader } from './frame.mjs';
import { hit } from './failpoints.mjs';
import { buildSnapshot } from './snapshot.mjs';

export function compactionTempPath(walFile) {
  return `${walFile}.compact`;
}

/**
 * Writes and installs the next generation of the log. Returns the snapshot and
 * the size of the new file. If this throws, the old log is still in place.
 */
export function compactLog({ wal, ops, state, generation, now, config }) {
  const nextGeneration = generation + 1;
  const snapshot = buildSnapshot(state, now, config);
  const bytes = Buffer.concat([encodeHeader(nextGeneration), encodeFrame(snapshot)]);
  const tempPath = compactionTempPath(wal.file);

  try {
    // Exclusive, so two compactors can never write the same temp file.
    ops.create(tempPath, { exclusive: true });
    ops.writeAt(tempPath, bytes, 0);
    hit('compact.after-tmp-write', { generation: nextGeneration });
    hit('compact.before-rename', { generation: nextGeneration });
    ops.rename(tempPath, wal.file);
    hit('compact.after-rename', { generation: nextGeneration });
    ops.sync(wal.file);
    ops.syncDir(path.dirname(wal.file));
  } catch (err) {
    err.message = `compaction failed: ${err.message}`;
    throw err;
  }

  return { snapshot, generation: nextGeneration, size: bytes.length };
}

##### queue
// The public queue API. All calls are synchronous: each one takes the queue lock,
// catches up with the log, decides, appends, and returns once the record is on disk.

import { computeBackoff } from './backoff.mjs';
import { resolveOptions } from './config.mjs';
import { InvalidTransitionError, StaleLeaseError, UnknownJobError } from './errors.mjs';
import { hit } from './failpoints.mjs';
import { lookupKey } from './idempotency.mjs';
import { expiredLeases, pickNextReady } from './lease.mjs';
import { computeMetrics } from './metrics.mjs';
import {
  cancelRecord,
  claimRecord,
  completeRecord,
  deadRecord,
  enqueueRecord,
  expireRecord,
  failRecord,
  requeueRecord,
} from './records.mjs';
import { Store } from './store.mjs';

function errorText(error) {
  if (error instanceof Error) return error.message;
  return error === undefined ? 'unknown error' : String(error);
}

export class Queue {
  constructor(dir, options = {}) {
    this.dir = dir;
    this.config = resolveOptions(options);
    this.clock = this.config.clock;
    this.store = new Store(dir, this.config);
  }

  open() {
    this.store.open();
    return this;
  }

  close() {
    this.store.close();
  }

  #require(id) {
    const job = this.store.state.jobs.get(id);
    if (!job) throw new UnknownJobError(id);
    return job;
  }

  #requireLease(job, token) {
    if (job.status !== 'leased') {
      throw new StaleLeaseError(job.id, token, job.fence);
    }
  }

  #newEnqueue(type, payload, options, now, offset = 0) {
    const key = options.key ?? null;
    return enqueueRecord({
      id: `j${this.store.state.seq + offset + 1}`,
      type,
      payload: payload ?? null,
      key,
      priority: options.priority ?? 0,
      maxAttempts: options.maxAttempts ?? this.config.maxAttempts,
      availableAt: now + (options.delayMs ?? 0),
      at: now,
    });
  }

  /**
   * Adds a job. With `key`, a repeat call while the key is remembered returns the
   * original job (and its result, if it has finished) with `deduped: true`.
   */
  enqueue(type, payload, options = {}) {
    const key = options.key ?? null;
    if (key) {
      this.store.refresh();
      const seen = lookupKey(this.store.state, key, this.clock.now(), this.config.idempotencyTtlMs);
      if (seen) return { ...seen, deduped: true };
    }
    hit('enqueue.before-lock', { key });
    return this.store.withLock(() => {
      const now = this.clock.now();
      const record = this.#newEnqueue(type, payload, options, now);
      this.store.append([record]);
      this.store.maybeCompact();
      return { id: record.id, status: 'ready', deduped: false };
    });
  }

  /**
   * Adds several jobs under one lock and one fsync. A crash part way through can
   * leave a prefix of the batch behind, so use keys if you will retry the batch.
   */
  enqueueMany(items) {
    return this.store.withLock(() => {
      const now = this.clock.now();
      const results = [];
      const records = [];
      const fresh = new Map();
      for (const { type, payload, options = {} } of items) {
        const key = options.key ?? null;
        const seen = key
          ? fresh.get(key) ?? lookupKey(this.store.state, key, now, this.config.idempotencyTtlMs)
          : null;
        if (seen) {
          results.push({ ...seen, deduped: true });
          continue;
        }
        const record = this.#newEnqueue(type, payload, options, now, records.length);
        records.push(record);
        const result = { id: record.id, status: 'ready', result: null };
        if (key) fresh.set(key, result);
        results.push({ id: record.id, status: 'ready', deduped: false });
      }
      if (records.length) this.store.append(records);
      this.store.maybeCompact();
      return results;
    });
  }

  /**
   * Leases the next due job to `worker`. Returns null when nothing is due.
   * The returned `token` must accompany every later call about this attempt.
   */
  claim(worker, { leaseMs = this.config.leaseMs, types = null } = {}) {
    this.store.refresh();
    const job = pickNextReady(this.store.state, this.clock.now(), types);
    if (!job) return null;
    const fence = job.fence + 1;
    hit('claim.before-lock', { worker });
    return this.store.withLock(() => {
      const now = this.clock.now();
      const leaseUntil = now + leaseMs;
      this.store.append([claimRecord({ id: job.id, worker, fence, leaseUntil, at: now })]);
      this.store.maybeCompact();
      const claimed = this.store.state.jobs.get(job.id);
      return {
        id: claimed.id,
        type: claimed.type,
        payload: claimed.payload,
        attempt: claimed.attempts,
        token: fence,
        leaseUntil,
      };
    });
  }

  /** Extends a lease. Throws StaleLeaseError if the lease is no longer ours. */
  heartbeat(id, token, { leaseMs = this.config.leaseMs } = {}) {
    // Heartbeats fire several times per lease. An fsync for each one would dominate
    // the log, so they only extend the lease this process is holding.
    const job = this.#require(id);
    this.#requireLease(job, token);
    const leaseUntil = this.clock.now() + leaseMs;
    job.lease.until = leaseUntil;
    return { leaseUntil };
  }

  /** Marks a job finished and stores its result. */
  complete(id, token, result = null) {
    hit('complete.before-lock', { id });
    return this.store.withLock(() => {
      const job = this.#require(id);
      this.#requireLease(job, token);
      const record = completeRecord({ id, fence: token, result, at: this.clock.now() });
      // Completions are the hot path. The next synced append flushes this one too.
      this.store.append([record], { sync: false });
      this.store.maybeCompact();
      return { id, status: 'done' };
    });
  }

  /** Reports a failed attempt. The job retries after a backoff, or goes dead. */
  fail(id, token, error) {
    return this.store.withLock(() => {
      const job = this.#require(id);
      this.#requireLease(job, token);
      const now = this.clock.now();
      const text = errorText(error);
      if (job.attempts >= job.maxAttempts) {
        this.store.append([deadRecord({ id, fence: token, error: text, at: now })]);
        return { id, status: 'dead', retryAt: null };
      }
      const delayMs = computeBackoff(job.attempts, this.config.backoff, id);
      this.store.append([failRecord({ id, fence: token, error: text, delayMs, at: now })]);
      this.store.maybeCompact();
      return { id, status: 'ready', retryAt: now + delayMs };
    });
  }

  /** Returns jobs whose lease ran out to the queue. Safe to call from anywhere. */
  reapExpired() {
    this.store.refresh();
    const expired = expiredLeases(this.store.state, this.clock.now());
    if (expired.length === 0) return [];
    hit('reap.before-lock');
    return this.store.withLock(() => {
      const now = this.clock.now();
      const records = [];
      const reaped = [];
      for (const job of expired) {
        if (job.attempts >= job.maxAttempts) {
          records.push(deadRecord({ id: job.id, fence: job.fence, error: 'lease expired', at: now }));
          reaped.push({ id: job.id, status: 'dead' });
        } else {
          const delayMs = computeBackoff(job.attempts, this.config.backoff, job.id);
          records.push(expireRecord({ id: job.id, fence: job.fence, delayMs, at: now }));
          reaped.push({ id: job.id, status: 'ready', retryAt: now + delayMs });
        }
      }
      if (records.length) {
        this.store.append(records);
        this.store.maybeCompact();
      }
      return reaped;
    });
  }

  /** Stops a job that has not finished. Any worker holding it loses its lease. */
  cancel(id, { reason = 'cancelled' } = {}) {
    return this.store.withLock(() => {
      const job = this.#require(id);
      if (job.status !== 'ready' && job.status !== 'leased') {
        return { id, status: job.status, changed: false };
      }
      this.store.append([cancelRecord({ id, fence: job.fence, error: reason, at: this.clock.now() })]);
      this.store.maybeCompact();
      return { id, status: 'cancelled', changed: true };
    });
  }

  /** Gives a dead job a fresh set of attempts, runnable now. */
  requeueDead(id) {
    return this.store.withLock(() => {
      const job = this.#require(id);
      if (job.status !== 'dead') throw new InvalidTransitionError(id, job.status, 'ready');
      this.store.append([requeueRecord({ id, at: this.clock.now() })]);
      this.store.maybeCompact();
      return { id, status: 'ready' };
    });
  }

  getJob(id) {
    return this.store.withLock(() => {
      const job = this.store.state.jobs.get(id);
      return job ? structuredClone(job) : null;
    });
  }

  listJobs() {
    return this.store.withLock(() => [...this.store.state.jobs.values()].map((job) => structuredClone(job)));
  }

  stats() {
    return this.store.withLock(() => {
      const counts = { ready: 0, leased: 0, done: 0, dead: 0, cancelled: 0 };
      for (const job of this.store.state.jobs.values()) counts[job.status] += 1;
      return { ...counts, total: this.store.state.jobs.size, ...this.store.describe() };
    });
  }

  /** Operational numbers, for dashboards. See docs/operations.md. */
  metrics() {
    return this.store.withLock(() => ({
      ...computeMetrics(this.store.state, this.clock.now()),
      ...this.store.describe(),
    }));
  }

  /** Rewrites the log as one snapshot. Throws if it could not; the old log stays. */
  compact() {
    return this.store.withLock(() => this.store.compact());
  }
}

export function openQueue(dir, options = {}) {
  return new Queue(dir, options).open();
}

##### lease
// Lease rules, as pure functions over the replayed state.

/** A lease has expired once the clock reaches its deadline. */
export function isLeaseExpired(job, now) {
  return job.status === 'leased' && now >= job.lease.until;
}

export function expiredLeases(state, now) {
  const expired = [];
  for (const job of state.jobs.values()) {
    if (isLeaseExpired(job, now)) expired.push(job);
  }
  return expired;
}

function runsBefore(a, b) {
  if (a.priority !== b.priority) return a.priority > b.priority;
  if (a.availableAt !== b.availableAt) return a.availableAt < b.availableAt;
  return a.seq < b.seq;
}

/** The highest-priority due job; among equals, the one due longest, then the oldest. */
export function pickNextReady(state, now, types = null) {
  let best = null;
  for (const job of state.jobs.values()) {
    if (job.status !== 'ready' || job.availableAt > now) continue;
    if (types && !types.includes(job.type)) continue;
    if (!best || runsBefore(job, best)) best = job;
  }
  return best;
}

##### backoff
// Retry delay schedule.

function fractionFor(salt, attempt) {
  let hash = 2166136261;
  for (const ch of `${salt}:${attempt}`) {
    hash = Math.imul(hash ^ ch.charCodeAt(0), 16777619);
  }
  return (hash >>> 0) / 2 ** 32;
}

/**
 * Delay before a job may run again, given how many attempts it has used.
 * delay = min(maxMs, baseMs * factor^(attempts - 1)), then reduced by up to
 * `jitter` of itself. The reduction is derived from `salt` and the attempt so
 * that every process computes the same number.
 */
export function computeBackoff(attempts, policy, salt = '') {
  const exponent = Math.max(0, attempts - 1);
  const raw = Math.min(policy.maxMs, policy.baseMs * policy.factor ** exponent);
  const reduction = policy.jitter > 0 ? raw * policy.jitter * fractionFor(salt, attempts) : 0;
  return Math.round(raw - reduction);
}

##### idempotency
// Idempotency keys map a caller-chosen key to the job it created.

/** Returns what a repeat enqueue with `key` should see, or null if the key is free. */
export function lookupKey(state, key, now, ttlMs) {
  const entry = state.idem.get(key);
  if (!entry) return null;
  if (now - entry.at >= ttlMs) return null;
  const job = state.jobs.get(entry.id);
  if (job) return { id: job.id, status: job.status, result: job.result ?? null };
  return { id: entry.id, status: entry.status ?? 'done', result: entry.result ?? null };
}

##### config
// Option defaults and validation for openQueue().

import { ConfigError } from './errors.mjs';
import { SystemClock } from './clock.mjs';

const HOUR = 60 * 60 * 1000;

const DEFAULTS = {
  leaseMs: 30_000,
  lockTimeoutMs: 10_000,
  compactAfterBytes: 4 * 1024 * 1024,
  retainCompletedMs: 24 * HOUR,
  idempotencyTtlMs: 7 * 24 * HOUR,
  maxAttempts: 5,
};

const DEFAULT_BACKOFF = { baseMs: 1_000, factor: 2, maxMs: 60_000, jitter: 0 };

function requireNonNegative(name, value) {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
    throw new ConfigError(`${name} must be a non-negative number, got ${value}`);
  }
}

export function resolveOptions(options = {}) {
  const config = { ...DEFAULTS, ...options };
  config.clock = options.clock ?? new SystemClock();
  config.backoff = { ...DEFAULT_BACKOFF, ...(options.backoff ?? {}) };

  for (const key of Object.keys(DEFAULTS)) requireNonNegative(key, config[key]);
  for (const key of ['baseMs', 'maxMs', 'jitter']) {
    requireNonNegative(`backoff.${key}`, config.backoff[key]);
  }
  if (config.backoff.factor < 1) throw new ConfigError('backoff.factor must be at least 1');
  if (config.backoff.jitter > 1) throw new ConfigError('backoff.jitter must be at most 1');
  if (config.maxAttempts < 1) throw new ConfigError('maxAttempts must be at least 1');
  if (typeof config.clock.now !== 'function') throw new ConfigError('clock must have a now() method');
  return config;
}

