##### inspect
// Read-only view of a log, for tools and debugging. Takes no lock and changes
// nothing, so a torn tail is reported here and left for the next writer.

import fs from 'node:fs';
import path from 'node:path';
import { decodeHeader, HEADER_SIZE, scanFrames } from './frame.mjs';
import { WAL_FILE } from './store.mjs';

export function inspectLog(dir) {
  const file = path.join(dir, WAL_FILE);
  const bytes = fs.readFileSync(file);
  const header = decodeHeader(bytes, file);
  const { frames, end, tail } = scanFrames(bytes.subarray(HEADER_SIZE), HEADER_SIZE);
  return { file, header, frames, end, tail, size: bytes.length };
}

export function describeRecord(record) {
  switch (record.t) {
    case 'enqueue':
      return `enqueue ${record.id} type=${record.type}${record.key ? ` key=${record.key}` : ''}`;
    case 'claim':
      return `claim ${record.id} worker=${record.worker} fence=${record.fence} until=${record.leaseUntil}`;
    case 'heartbeat':
      return `heartbeat ${record.id} fence=${record.fence} until=${record.leaseUntil}`;
    case 'complete':
      return `complete ${record.id} fence=${record.fence}`;
    case 'fail':
    case 'expire':
      return `${record.t} ${record.id} fence=${record.fence} delayMs=${record.delayMs}`;
    case 'cancel':
      return `cancel ${record.id} fence=${record.fence}`;
    case 'dead':
      return `dead ${record.id} fence=${record.fence} error=${record.error}`;
    case 'snapshot':
      return `snapshot jobs=${record.jobs.length} seq=${record.seq}`;
    default:
      return `${record.t} ${record.id ?? ''}`.trim();
  }
}

##### cli
#!/usr/bin/env node
// Operator tool.
//
//   node src/cli.mjs inspect <dir>        print every record in the log
//   node src/cli.mjs stats <dir>          print job counts
//   node src/cli.mjs compact <dir>        compact now
//   node src/cli.mjs tail <dir>           follow the log, keeping it open
//   node src/cli.mjs metrics <dir>        print operational numbers
//   node src/cli.mjs requeue <dir> <id>   give a dead job a fresh set of attempts
//   node src/cli.mjs cancel <dir> <id>    stop a job that has not finished

import fs from 'node:fs';
import path from 'node:path';
import { HEADER_SIZE, scanFrames } from './frame.mjs';
import { describeRecord, inspectLog } from './inspect.mjs';
import { openQueue } from './queue.mjs';
import { WAL_FILE } from './store.mjs';

function usage() {
  console.error('usage: cli.mjs <inspect|stats|compact|tail|metrics|requeue|cancel> <dir> [id]');
  process.exitCode = 2;
}

function inspect(dir) {
  const view = inspectLog(dir);
  console.log(`${view.file}: generation ${view.header.generation}, ${view.size} bytes`);
  for (const frame of view.frames) console.log(`${frame.offset}\t${describeRecord(frame.record)}`);
  if (view.tail) console.log(`${view.tail.offset}\tincomplete tail (${view.tail.reason}, ${view.tail.bytes} bytes)`);
}

function stats(dir) {
  const queue = openQueue(dir);
  console.log(JSON.stringify(queue.stats(), null, 2));
  queue.close();
}

function compact(dir) {
  const queue = openQueue(dir);
  console.log(JSON.stringify(queue.compact()));
  queue.close();
}

function metrics(dir) {
  const queue = openQueue(dir);
  console.log(JSON.stringify(queue.metrics(), null, 2));
  queue.close();
}

function requeue(dir, id) {
  const queue = openQueue(dir);
  console.log(JSON.stringify(queue.requeueDead(id)));
  queue.close();
}

function cancel(dir, id) {
  const queue = openQueue(dir);
  console.log(JSON.stringify(queue.cancel(id)));
  queue.close();
}

// Keeps a read handle on the log so that it sees every byte as it arrives.
function tail(dir) {
  const fd = fs.openSync(path.join(dir, WAL_FILE), 'r');
  let offset = HEADER_SIZE;
  const timer = setInterval(() => {
    const size = fs.fstatSync(fd).size;
    if (size <= offset) return;
    const bytes = Buffer.alloc(size - offset);
    fs.readSync(fd, bytes, 0, bytes.length, offset);
    const { frames, end } = scanFrames(bytes, offset);
    for (const frame of frames) console.log(describeRecord(frame.record));
    offset = end;
  }, 200);
  process.on('SIGINT', () => {
    clearInterval(timer);
    fs.closeSync(fd);
  });
}

const [command, dir, id] = process.argv.slice(2);
const commands = { inspect, stats, compact, tail, metrics, requeue, cancel };
if (!commands[command] || !dir) usage();
else commands[command](dir, id);

##### metrics
// Numbers an operator wants on a dashboard, computed from the replayed state.

export function computeMetrics(state, now) {
  const byType = {};
  let oldestReadyAt = null;
  let dueNow = 0;
  let delayed = 0;
  let nextLeaseExpiry = null;
  const workers = new Set();
  let retriedJobs = 0;

  for (const job of state.jobs.values()) {
    const row = (byType[job.type] ??= { ready: 0, leased: 0, done: 0, dead: 0, cancelled: 0 });
    row[job.status] += 1;
    if (job.attempts > 1) retriedJobs += 1;

    if (job.status === 'ready') {
      if (job.availableAt <= now) {
        dueNow += 1;
        if (oldestReadyAt === null || job.availableAt < oldestReadyAt) oldestReadyAt = job.availableAt;
      } else {
        delayed += 1;
      }
    }
    if (job.status === 'leased') {
      workers.add(job.lease.worker);
      if (nextLeaseExpiry === null || job.lease.until < nextLeaseExpiry) nextLeaseExpiry = job.lease.until;
    }
  }

  return {
    byType,
    dueNow,
    delayed,
    retriedJobs,
    oldestReadyAgeMs: oldestReadyAt === null ? 0 : now - oldestReadyAt,
    nextLeaseExpiryMs: nextLeaseExpiry === null ? null : nextLeaseExpiry - now,
    activeWorkers: workers.size,
    idempotencyKeys: state.idem.size,
    jobsEverEnqueued: state.seq,
  };
}

##### pool
// WorkerPool: starts worker processes, replaces the ones that die, and returns
// jobs to the queue when their lease runs out.

import { fork } from 'node:child_process';
import { EventEmitter } from 'node:events';
import { fileURLToPath } from 'node:url';
import { sleep } from '../clock.mjs';
import { createLogger } from '../logger.mjs';
import { openQueue } from '../queue.mjs';
import { STOP } from './protocol.mjs';

const CHILD_PATH = fileURLToPath(new URL('./child.mjs', import.meta.url));
const STOP_GRACE_MS = 2_000;

const log = createLogger('pool');

export class WorkerPool extends EventEmitter {
  constructor({
    dir,
    handlers,
    size = 2,
    leaseMs = 30_000,
    heartbeatMs,
    pollMs = 20,
    reapMs,
    types = null,
    env = {},
    queue = {},
    maxRespawns = 100,
  }) {
    super();
    this.options = { dir, handlers, leaseMs, heartbeatMs, pollMs, types, queue };
    this.size = size;
    this.reapMs = reapMs ?? Math.max(20, Math.floor(leaseMs / 2));
    this.env = env;
    this.maxRespawns = maxRespawns;
    this.children = new Map();
    this.incarnation = 0;
    this.respawns = 0;
    this.stopping = false;
    this.reaper = null;
    this.queue = null;
  }

  start() {
    this.queue = openQueue(this.options.dir, this.options.queue);
    for (let i = 0; i < this.size; i += 1) this.#spawn();
    this.reaper = setInterval(() => this.#reap(), this.reapMs);
    return this;
  }

  #reap() {
    try {
      this.queue.reapExpired();
    } catch (err) {
      this.emit('error-event', err);
    }
  }

  #spawn() {
    this.incarnation += 1;
    const workerId = `w${this.incarnation}`;
    const child = fork(CHILD_PATH, [JSON.stringify({ ...this.options, workerId })], {
      env: { ...process.env, ...this.env },
      silent: true,
      windowsHide: true,
    });
    child.stdout.resume();
    child.stderr.on('data', (chunk) => this.emit('stderr', chunk.toString()));
    child.on('message', (message) => this.emit('message', message));
    child.on('error', (err) => this.emit('error-event', err));
    child.on('exit', (code, signal) => this.#onExit(workerId, code, signal));
    this.children.set(workerId, child);
  }

  #onExit(workerId, code, signal) {
    this.children.delete(workerId);
    this.emit('exit', { workerId, code, signal });
    log.info('worker exited', { workerId, code, signal, stopping: this.stopping });
    if (this.stopping) return;
    if (this.respawns < this.maxRespawns) {
      this.respawns += 1;
      this.#spawn();
    }
  }

  /** Resolves once no job is ready or leased. Rejects if that takes too long. */
  async drain({ timeoutMs = 60_000 } = {}) {
    const deadline = performance.now() + timeoutMs;
    for (;;) {
      const { ready, leased } = this.queue.stats();
      if (ready === 0 && leased === 0) return;
      if (performance.now() >= deadline) {
        throw new Error(`drain timed out with ${ready} ready and ${leased} leased jobs`);
      }
      await sleep(25);
    }
  }

  /** Stops every worker and waits for them to go. */
  async stop() {
    this.stopping = true;
    clearInterval(this.reaper);
    const waits = [];
    for (const child of this.children.values()) {
      waits.push(new Promise((resolve) => child.once('exit', resolve)));
      if (child.connected) child.send({ kind: STOP }, () => {});
    }
    const timer = setTimeout(() => {
      for (const child of this.children.values()) child.kill();
    }, STOP_GRACE_MS);
    await Promise.all(waits);
    clearTimeout(timer);
    this.queue?.close();
  }
}

##### child
// Entry point of a worker process. Started by WorkerPool with one JSON argument.

import { openQueue } from '../queue.mjs';
import { send, STOP, WORKER_READY } from './protocol.mjs';
import { loadHandlers } from './registry.mjs';
import { JobRunner } from './runner.mjs';

const options = JSON.parse(process.argv[2]);

// A worker never outlives its pool: the channel closing means the parent is gone.
process.on('disconnect', () => process.exit(0));

const handlers = await loadHandlers(options.handlers);
const queue = openQueue(options.dir, options.queue);

const runner = new JobRunner({
  queue,
  workerId: options.workerId,
  handlers,
  leaseMs: options.leaseMs,
  heartbeatMs: options.heartbeatMs,
  pollMs: options.pollMs,
  types: options.types,
  emit: (message) => send({ ...message, workerId: options.workerId }),
});

process.on('message', (message) => {
  if (message?.kind === STOP) runner.stop();
});

send({ kind: WORKER_READY, workerId: options.workerId });
await runner.run();
queue.close();
process.exit(0);

##### protocol
// Messages between a WorkerPool and its child processes, over the fork() channel.

export const WORKER_READY = 'ready';
export const JOB_STARTED = 'job-started';
export const JOB_COMPLETED = 'job-completed';
export const JOB_FAILED = 'job-failed';
export const JOB_FENCED = 'job-fenced';
export const WORKER_ERROR = 'worker-error';
export const STOP = 'stop';

/** Sends if the channel is still open. A dead parent is not this worker's problem. */
export function send(message) {
  if (process.connected) {
    try {
      process.send(message);
    } catch {
      // The channel closed between the check and the send.
    }
  }
}

##### registry
// Loads a handlers module. Each export is either a function or an object of the
// form { run, timeoutMs }.

import { pathToFileURL } from 'node:url';
import { ConfigError } from '../errors.mjs';

function normalise(type, entry) {
  if (typeof entry === 'function') return { run: entry, timeoutMs: null };
  if (entry && typeof entry.run === 'function') {
    const timeoutMs = entry.timeoutMs ?? null;
    if (timeoutMs !== null && !(timeoutMs > 0)) {
      throw new ConfigError(`handler ${type}: timeoutMs must be positive`);
    }
    return { run: entry.run, timeoutMs };
  }
  throw new ConfigError(`handler ${type} must be a function or { run, timeoutMs }`);
}

export function normaliseHandlers(raw) {
  const handlers = new Map();
  for (const [type, entry] of Object.entries(raw)) handlers.set(type, normalise(type, entry));
  return handlers;
}

export async function loadHandlers(file) {
  const module = await import(pathToFileURL(file).href);
  return normaliseHandlers(module.default ?? module);
}

/** Runs a handler, rejecting if it outlasts its timeout. The signal tells it to stop. */
export function runWithTimeout(handler, payload, context, abort) {
  const running = Promise.resolve().then(() => handler.run(payload, context));
  if (handler.timeoutMs === null) return running;
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => {
      abort.abort();
      reject(new Error(`handler timed out after ${handler.timeoutMs}ms`));
    }, handler.timeoutMs);
  });
  return Promise.race([running, timeout]).finally(() => clearTimeout(timer));
}

##### runner
// JobRunner: the loop a worker process runs. Claim a job, run its handler with a
// heartbeat going, then record the outcome.

import { sleep } from '../clock.mjs';
import { StaleLeaseError, UnknownJobError, WalqError } from '../errors.mjs';
import { hit } from '../failpoints.mjs';
import { JOB_COMPLETED, JOB_FAILED, JOB_FENCED, JOB_STARTED, WORKER_ERROR } from './protocol.mjs';
import { runWithTimeout } from './registry.mjs';

export class JobRunner {
  constructor({ queue, workerId, handlers, leaseMs, heartbeatMs, pollMs = 20, types = null, emit = () => {} }) {
    this.queue = queue;
    this.workerId = workerId;
    this.handlers = handlers;
    this.leaseMs = leaseMs ?? queue.config.leaseMs;
    this.heartbeatMs = heartbeatMs ?? Math.max(10, Math.floor(this.leaseMs / 3));
    this.pollMs = pollMs;
    this.types = types;
    this.emit = emit;
    this.stopping = false;
  }

  stop() {
    this.stopping = true;
  }

  async run() {
    while (!this.stopping) {
      const job = this.#claimNext();
      if (job) await this.execute(job);
      else await sleep(this.pollMs);
    }
  }

  #claimNext() {
    try {
      return this.queue.claim(this.workerId, { leaseMs: this.leaseMs, types: this.types });
    } catch (err) {
      if (!(err instanceof WalqError)) throw err;
      this.emit({ kind: WORKER_ERROR, error: err.message });
      return null;
    }
  }

  async execute(job) {
    const { id, token } = job;
    hit('job.before-handler', { id });
    this.emit({ kind: JOB_STARTED, id, attempt: job.attempt, token });

    const abort = new AbortController();
    const beat = setInterval(() => {
      try {
        this.queue.heartbeat(id, token, { leaseMs: this.leaseMs });
      } catch (err) {
        if (err instanceof StaleLeaseError) {
          clearInterval(beat);
          abort.abort();
        } else {
          this.emit({ kind: WORKER_ERROR, error: err.message });
        }
      }
    }, this.heartbeatMs);

    let result;
    try {
      const handler = this.handlers.get(job.type);
      if (!handler) throw new Error(`no handler for job type ${job.type}`);
      result = await runWithTimeout(
        handler,
        job.payload,
        { id, attempt: job.attempt, token, workerId: this.workerId, signal: abort.signal },
        abort,
      );
    } catch (err) {
      clearInterval(beat);
      await this.#report(id, () => this.queue.fail(id, token, err), JOB_FAILED, err);
      return;
    }

    clearInterval(beat);
    hit('job.after-handler', { id });
    await this.#report(id, () => this.queue.complete(id, token, result), JOB_COMPLETED);
    hit('job.after-complete', { id });
  }

  // A fenced worker has lost the job to someone else. That is an expected end for
  // this attempt, not an error.
  async #report(id, call, kind, cause) {
    try {
      call();
      this.emit({ kind, id, error: cause?.message });
    } catch (err) {
      if (err instanceof StaleLeaseError || err instanceof UnknownJobError) {
        this.emit({ kind: JOB_FENCED, id });
      } else {
        this.emit({ kind: WORKER_ERROR, id, error: err.message });
      }
    }
  }
}

