import assert from 'node:assert/strict';
import { test } from 'node:test';
import { ConfigError, ManualClock, openQueue, QueueClosedError, StaleLeaseError, UnknownJobError } from '../src/index.mjs';
import { tempDir } from './helpers/tmp.mjs';

const OPTIONS = { backoff: { baseMs: 100, factor: 2, maxMs: 1_000 } };

function setup(t, extra = {}) {
  const clock = new ManualClock(1_000);
  const dir = tempDir(t);
  const queue = openQueue(dir, { clock, ...OPTIONS, ...extra });
  return { clock, dir, queue };
}

test('a job goes from enqueue to claim to complete', (t) => {
  const { queue } = setup(t);
  const { id } = queue.enqueue('mail', { to: 'someone' });
  const job = queue.claim('w1', { leaseMs: 500 });
  assert.equal(job.id, id);
  assert.deepEqual(job.payload, { to: 'someone' });
  assert.equal(job.attempt, 1);
  queue.complete(job.id, job.token, { sent: true });
  const stored = queue.getJob(id);
  assert.equal(stored.status, 'done');
  assert.deepEqual(stored.result, { sent: true });
  assert.equal(queue.claim('w1'), null);
});

test('jobs come out oldest first', (t) => {
  const { queue } = setup(t);
  const ids = ['a', 'b', 'c'].map((name) => queue.enqueue('x', name).id);
  const order = ids.map(() => queue.claim('w').id);
  assert.deepEqual(order, ids);
});

test('a delayed job waits for its time', (t) => {
  const { queue, clock } = setup(t);
  const { id } = queue.enqueue('x', null, { delayMs: 200 });
  assert.equal(queue.claim('w'), null);
  clock.advance(199);
  assert.equal(queue.claim('w'), null);
  clock.advance(1);
  assert.equal(queue.claim('w').id, id);
});

test('claim can filter by job type', (t) => {
  const { queue } = setup(t);
  queue.enqueue('a', 1);
  const { id } = queue.enqueue('b', 2);
  assert.equal(queue.claim('w', { types: ['b'] }).id, id);
  assert.equal(queue.claim('w', { types: ['b'] }), null);
});

test('state survives closing and reopening', (t) => {
  const { queue, dir, clock } = setup(t);
  const { id: first } = queue.enqueue('x', 1);
  const { id: second } = queue.enqueue('x', 2);
  const job = queue.claim('w', { leaseMs: 500 });
  queue.complete(job.id, job.token, 'ok');
  queue.close();

  const reopened = openQueue(dir, { clock, ...OPTIONS });
  assert.equal(reopened.getJob(first).status, 'done');
  assert.equal(reopened.getJob(second).status, 'ready');
  assert.equal(reopened.claim('w').id, second);
});

test('failing a job schedules a retry with backoff', (t) => {
  const { queue, clock } = setup(t);
  const { id } = queue.enqueue('x', null);
  const job = queue.claim('w');
  const outcome = queue.fail(job.id, job.token, new Error('boom'));
  assert.equal(outcome.status, 'ready');
  assert.equal(outcome.retryAt, clock.now() + 100);
  assert.equal(queue.claim('w'), null);
  clock.advance(100);
  const again = queue.claim('w');
  assert.equal(again.id, id);
  assert.equal(again.attempt, 2);
  assert.equal(queue.getJob(id).lastError, 'boom');
});

test('a job goes dead when its attempts run out', (t) => {
  const { queue, clock } = setup(t);
  const { id } = queue.enqueue('x', null, { maxAttempts: 2 });
  let job = queue.claim('w');
  queue.fail(job.id, job.token, 'one');
  clock.advance(100);
  job = queue.claim('w');
  assert.equal(queue.fail(job.id, job.token, 'two').status, 'dead');
  assert.equal(queue.getJob(id).status, 'dead');
  clock.advance(10_000);
  assert.equal(queue.claim('w'), null);
});

test('an idempotency key returns the first job', (t) => {
  const { queue } = setup(t);
  const first = queue.enqueue('x', 1, { key: 'k' });
  const second = queue.enqueue('x', 2, { key: 'k' });
  assert.equal(first.deduped, false);
  assert.equal(second.deduped, true);
  assert.equal(second.id, first.id);
  assert.equal(queue.stats().total, 1);
});

test('enqueueMany writes a batch and honours keys inside it', (t) => {
  const { queue } = setup(t);
  queue.enqueue('x', 0, { key: 'old' });
  const results = queue.enqueueMany([
    { type: 'x', payload: 1, options: { key: 'old' } },
    { type: 'x', payload: 2, options: { key: 'new' } },
    { type: 'x', payload: 3, options: { key: 'new' } },
    { type: 'x', payload: 4 },
  ]);
  assert.deepEqual(results.map((r) => r.deduped), [true, false, true, false]);
  assert.equal(results[1].id, results[2].id);
  assert.equal(queue.stats().total, 3);
});

test('unknown jobs and closed queues raise their own errors', (t) => {
  const { queue } = setup(t);
  assert.throws(() => queue.complete('nope', 1), UnknownJobError);
  queue.close();
  assert.throws(() => queue.stats(), QueueClosedError);
});

test('completing a job twice is refused', (t) => {
  const { queue } = setup(t);
  queue.enqueue('x', null);
  const job = queue.claim('w');
  queue.complete(job.id, job.token);
  assert.throws(() => queue.fail(job.id, job.token, 'late'), StaleLeaseError);
});

test('bad options are rejected', (t) => {
  assert.throws(() => openQueue(tempDir(t), { leaseMs: -1 }), ConfigError);
  assert.throws(() => openQueue(tempDir(t), { backoff: { factor: 0.5 } }), ConfigError);
});

##### worker-pool
import assert from 'node:assert/strict';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';
import { openQueue, WorkerPool } from '../src/index.mjs';
import { defer, readLedger, tempDir } from './helpers/tmp.mjs';

const HANDLERS = fileURLToPath(new URL('./helpers/handlers.mjs', import.meta.url));

function setup(t, poolOptions = {}, queueOptions = {}) {
  const dir = tempDir(t);
  const ledger = path.join(dir, 'runs.jsonl');
  const queue = openQueue(dir, queueOptions);
  const pool = new WorkerPool({
    dir,
    handlers: HANDLERS,
    queue: queueOptions,
    pollMs: 5,
    ...poolOptions,
    env: { WALQ_TEST_LEDGER: ledger, ...(poolOptions.env ?? {}) },
  });
  defer(t, () => pool.stop());
  return { dir, ledger, queue, pool };
}

function startsPerJob(ledger) {
  const counts = new Map();
  for (const entry of readLedger(ledger)) {
    if (entry.event === 'start') counts.set(entry.id, (counts.get(entry.id) ?? 0) + 1);
  }
  return counts;
}

test('a pool runs every job and stops cleanly', { timeout: 30_000 }, async (t) => {
  const { queue, pool } = setup(t, { size: 1 });
  for (let i = 0; i < 10; i += 1) queue.enqueue('quick', { n: i });
  pool.start();
  await pool.drain({ timeoutMs: 20_000 });
  assert.equal(queue.stats().done, 10);
  assert.deepEqual(queue.listJobs()[3].result, { echoed: { n: 3 } });
});

test('four workers sharing a queue run each job once', { timeout: 30_000 }, async (t) => {
  const { queue, pool, ledger } = setup(t, { size: 4 });
  const jobs = [];
  for (let i = 0; i < 60; i += 1) jobs.push({ type: 'quick', payload: { n: i } });
  queue.enqueueMany(jobs);
  pool.start();
  await pool.drain({ timeoutMs: 20_000 });
  const counts = startsPerJob(ledger);
  assert.equal(counts.size, 60);
  for (const [id, runs] of counts) assert.equal(runs, 1, `job ${id} ran ${runs} times`);
});

test('a job longer than its lease is not run twice while its worker is alive', { timeout: 30_000 }, async (t) => {
  const { queue, pool, ledger } = setup(t, { size: 2, leaseMs: 1_000, heartbeatMs: 100 }, { backoff: { baseMs: 20, factor: 2, maxMs: 100 } });
  const { id } = queue.enqueue('slow', { ms: 2_500 });
  pool.start();
  await pool.drain({ timeoutMs: 20_000 });
  assert.equal(startsPerJob(ledger).get(id), 1);
  assert.equal(queue.getJob(id).attempts, 1);
});

test('a failing handler is retried until it succeeds', { timeout: 30_000 }, async (t) => {
  const backoff = { baseMs: 20, factor: 2, maxMs: 100 };
  const { queue, pool, ledger } = setup(t, { size: 1 }, { backoff });
  const { id } = queue.enqueue('flaky', { succeedOn: 3 });
  pool.start();
  await pool.drain({ timeoutMs: 20_000 });
  assert.equal(queue.getJob(id).status, 'done');
  assert.equal(queue.getJob(id).result, 3);
  assert.equal(startsPerJob(ledger).get(id), 3);
});

test('a job whose worker is killed runs again after its lease runs out', { timeout: 30_000 }, async (t) => {
  const markers = tempDir(t);
  const backoff = { baseMs: 20, factor: 2, maxMs: 100 };
  const { queue, pool } = setup(
    t,
    {
      size: 1,
      leaseMs: 400,
      env: { WALQ_FAILPOINTS: 'job.before-handler=kill', WALQ_FAILPOINT_DIR: markers },
    },
    { backoff },
  );
  const { id } = queue.enqueue('quick', { n: 1 });
  pool.start();
  await pool.drain({ timeoutMs: 20_000 });
  const job = queue.getJob(id);
  assert.equal(job.status, 'done');
  assert.equal(job.attempts, 2);
});

##### backoff-schedule
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { computeBackoff } from '../src/index.mjs';

const POLICY = { baseMs: 100, factor: 2, maxMs: 1_000, jitter: 0 };

test('the delay doubles with each attempt', () => {
  assert.deepEqual([1, 2, 3, 4].map((n) => computeBackoff(n, POLICY)), [100, 200, 400, 800]);
});

test('the delay stops growing at the cap', () => {
  assert.equal(computeBackoff(5, POLICY), 1_000);
  assert.equal(computeBackoff(50, POLICY), 1_000);
});

test('jitter only shortens the delay, and every process gets the same number', () => {
  const policy = { ...POLICY, jitter: 0.5 };
  for (let attempt = 1; attempt <= 4; attempt += 1) {
    const delay = computeBackoff(attempt, policy, 'job-7');
    assert.ok(delay <= computeBackoff(attempt, POLICY));
    assert.ok(delay >= computeBackoff(attempt, POLICY) / 2);
    assert.equal(delay, computeBackoff(attempt, policy, 'job-7'));
  }
});

##### frame-format
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { crc32 } from '../src/crc32.mjs';
import { CorruptLogError } from '../src/errors.mjs';
import { decodeHeader, encodeFrame, encodeHeader, FRAME_OVERHEAD, HEADER_SIZE, scanFrames } from '../src/frame.mjs';

test('crc32 matches the published check value', () => {
  assert.equal(crc32(Buffer.from('123456789', 'ascii')), 0xcbf43926);
});

test('crc32 can be continued across chunks', () => {
  const whole = crc32(Buffer.from('hello world'));
  const parts = crc32(Buffer.from(' world'), crc32(Buffer.from('hello')));
  assert.equal(parts, whole);
});

test('a header round-trips and records its generation', () => {
  const header = encodeHeader(42);
  assert.equal(header.length, HEADER_SIZE);
  assert.equal(decodeHeader(header).generation, 42);
});

test('a damaged header is refused', () => {
  const header = encodeHeader(1);
  header[9] ^= 0xff;
  assert.throws(() => decodeHeader(header), CorruptLogError);
  assert.throws(() => decodeHeader(header.subarray(0, 8)), CorruptLogError);
});

test('frames round-trip through a scan', () => {
  const records = [{ t: 'a', n: 1 }, { t: 'b', text: 'hǸllo' }, { t: 'c', nested: { deep: [1, 2, 3] } }];
  const bytes = Buffer.concat(records.map(encodeFrame));
  const { frames, end, tail } = scanFrames(bytes, 100);
  assert.deepEqual(frames.map((f) => f.record), records);
  assert.equal(end, 100 + bytes.length);
  assert.equal(tail, null);
  assert.equal(frames[0].offset, 100);
  assert.equal(frames[0].size, FRAME_OVERHEAD + JSON.stringify(records[0]).length);
});

test('a frame cut short is reported as an incomplete tail', () => {
  const first = encodeFrame({ t: 'a' });
  const second = encodeFrame({ t: 'b', padding: 'x'.repeat(40) });
  const bytes = Buffer.concat([first, second.subarray(0, 20)]);
  const { frames, end, tail } = scanFrames(bytes);
  assert.equal(frames.length, 1);
  assert.equal(end, first.length);
  assert.equal(tail.offset, first.length);
});

#!/usr/bin/env node
// Long-running stress test: real worker processes, crash points, compaction under
// load. Runs rounds until its time budget is used, printing every run and every log
// record, then checks what happened against docs/guarantees.md.
//
//   npm run stress
//   node scripts/stress.mjs --seed 7 --seconds 90
//
// The exit code is 1 if any round broke a guarantee. Most problems here are
// intermittent, so one clean run does not prove much.

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describeRecord, inspectLog, openQueue, WorkerPool } from '../src/index.mjs';

const HANDLERS = fileURLToPath(new URL('./stress-handlers.mjs', import.meta.url));
const ROUND_LIMIT_MS = 18_000;

const CRASH_POINTS = [
  'wal.before-append',
  'wal.mid-append',
  'wal.after-write',
  'wal.after-fsync',
  'wal.mid-append#claim',
  'wal.mid-append#complete',
  'wal.after-fsync#complete',
  'job.before-handler',
  'job.after-handler',
  'job.after-complete',
  'compact.after-tmp-write',
  'compact.before-rename',
  'compact.after-rename',
];

function parseArgs(argv) {
  const args = { seed: 1, seconds: 90 };
  for (let i = 0; i < argv.length; i += 2) {
    if (argv[i] === '--seed') args.seed = Number(argv[i + 1]);
    if (argv[i] === '--seconds') args.seconds = Number(argv[i + 1]);
  }
  return args;
}

function makeRandom(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let z = state;
    z = Math.imul(z ^ (z >>> 15), z | 1);
    z ^= z + Math.imul(z ^ (z >>> 7), z | 61);
    return ((z ^ (z >>> 14)) >>> 0) / 2 ** 32;
  };
}

function pickMany(random, list, count) {
  const pool = [...list];
  const picked = [];
  while (picked.length < count && pool.length) {
    picked.push(pool.splice(Math.floor(random() * pool.length), 1)[0]);
  }
  return picked;
}

function readLedger(file) {
  if (!fs.existsSync(file)) return [];
  return fs.readFileSync(file, 'utf8').split('\n').filter(Boolean).map((line) => JSON.parse(line));
}

class Round {
  constructor(index, name) {
    this.index = index;
    this.name = name;
    this.dir = fs.mkdtempSync(path.join(os.tmpdir(), 'walq-stress-'));
    this.markers = path.join(this.dir, 'markers');
    fs.mkdirSync(this.markers);
    this.queueDir = path.join(this.dir, 'q');
    this.ledger = path.join(this.dir, 'ledger.jsonl');
    this.problems = [];
  }

  say(line) {
    console.log(`[round ${this.index} ${this.name}] ${line}`);
  }

  problem(line) {
    this.problems.push(line);
    console.log(`[round ${this.index} ${this.name}] PROBLEM: ${line}`);
  }

  dumpLog() {
    try {
      const view = inspectLog(this.queueDir);
      this.say(`log: generation ${view.header.generation}, ${view.size} bytes, ${view.frames.length} records`);
      for (const frame of view.frames) this.say(`  @${frame.offset} ${describeRecord(frame.record)}`);
      if (view.tail) this.say(`  @${view.tail.offset} incomplete tail: ${view.tail.reason}`);
      return view;
    } catch (err) {
      this.problem(`the log cannot be read: ${err.name}: ${err.message}`);
      return null;
    }
  }

  dumpLedger() {
    const entries = readLedger(this.ledger);
    for (const entry of entries) {
      this.say(`  ${entry.event} ${entry.id} attempt=${entry.attempt} token=${entry.token} worker=${entry.worker}`);
    }
    return entries;
  }

  cleanup() {
    fs.rmSync(this.dir, { recursive: true, force: true, maxRetries: 40, retryDelay: 50 });
  }
}

function checkLogHistory(round, view) {
  if (!view) return;
  const committed = new Map();
  for (const { record } of view.frames) {
    if (record.id === undefined) continue;
    if (committed.has(record.id)) round.problem(`${record.t} for ${record.id} after it committed`);
    if (record.t === 'complete') committed.set(record.id, record);
  }
}

async function runPool(round, poolOptions) {
  const pool = new WorkerPool({
    dir: round.queueDir,
    handlers: HANDLERS,
    pollMs: 5,
    maxRespawns: 60,
    ...poolOptions,
    env: { WALQ_STRESS_LEDGER: round.ledger, WALQ_FAILPOINT_DIR: round.markers, ...(poolOptions.env ?? {}) },
  });
  pool.on('exit', ({ workerId, code }) => round.say(`worker ${workerId} exited with code ${code}`));
  pool.on('stderr', (text) => round.say(`worker stderr: ${text.trim().slice(0, 400)}`));
  pool.on('error-event', (err) => round.say(`pool error: ${err.message}`));
  pool.on('message', (message) => {
    if (message.kind !== 'ready') round.say(`${message.workerId} ${message.kind} ${message.id ?? ''} ${message.error ?? ''}`);
  });
  pool.start();
  try {
    await pool.drain({ timeoutMs: ROUND_LIMIT_MS });
  } catch (err) {
    round.problem(err.message);
  }
  await pool.stop();
}

/** Many workers, short jobs, nothing goes wrong: every job must run exactly once. */
async function contentionRound(round, random) {
  const queue = openQueue(round.queueDir);
  const total = 40 + Math.floor(random() * 30);
  queue.enqueueMany(Array.from({ length: total }, (_, n) => ({ type: 'work', payload: { n, ms: Math.floor(random() * 4) } })));
  await runPool(round, { size: 4, leaseMs: 15_000 });

  const entries = round.dumpLedger();
  const view = round.dumpLog();
  checkLogHistory(round, view);
  const starts = new Map();
  for (const entry of entries) {
    if (entry.event === 'start') starts.set(entry.id, (starts.get(entry.id) ?? 0) + 1);
  }
  for (const [id, count] of starts) {
    if (count !== 1) round.problem(`job ${id} ran ${count} times with no crash involved`);
  }
  const stats = queue.stats();
  if (stats.done !== total) round.problem(`${stats.done} of ${total} jobs finished`);
  queue.close();
}

/** Workers die at chosen points: every job must still commit once, and none is lost. */
async function crashRound(round, random) {
  const queue = openQueue(round.queueDir, { backoff: { baseMs: 20, factor: 2, maxMs: 200 } });
  const total = 30;
  const acked = queue.enqueueMany(
    Array.from({ length: total }, (_, n) => ({
      type: n % 5 === 0 ? 'wobbly' : 'work',
      payload: { n, ms: Math.floor(random() * 6), succeedOn: 2 },
      options: { maxAttempts: 30 },
    })),
  );
  const points = pickMany(random, CRASH_POINTS.filter((p) => !p.startsWith('compact.')), 4);
  const rules = points.map((point) => `${point}=kill@${2 + Math.floor(random() * 12)}`).join(',');
  round.say(`armed: ${rules}`);
  await runPool(round, {
    size: 3,
    leaseMs: 900,
    env: { WALQ_FAILPOINTS: rules },
    queue: { backoff: { baseMs: 20, factor: 2, maxMs: 200 } },
  });

  round.dumpLedger();
  const view = round.dumpLog();
  checkLogHistory(round, view);
  for (const { id } of acked) {
    const job = queue.getJob(id);
    if (!job) round.problem(`job ${id} was acknowledged and has vanished`);
    else if (job.status !== 'done') round.problem(`job ${id} ended as ${job.status}`);
  }
  queue.close();
}

/** The log keeps being rewritten under the workers, and keys must keep working. */
async function compactionRound(round, random) {
  const options = { compactAfterBytes: 2_500, backoff: { baseMs: 20, factor: 2, maxMs: 200 } };
  const queue = openQueue(round.queueDir, options);
  const total = 40;
  const items = Array.from({ length: total }, (_, n) => ({
    type: 'work',
    payload: { n, ms: Math.floor(random() * 4) },
    options: { key: `key-${n}` },
  }));
  const first = queue.enqueueMany(items);

  const points = pickMany(random, CRASH_POINTS.filter((p) => p.startsWith('compact.')), 2);
  const rules = points.map((point) => `${point}=kill`).join(',');
  round.say(`armed: ${rules}`);

  const running = runPool(round, { size: 3, leaseMs: 900, env: { WALQ_FAILPOINTS: rules }, queue: options });
  for (let i = 0; i < 6; i += 1) {
    await new Promise((resolve) => setTimeout(resolve, 100));
    for (const again of queue.enqueueMany(items)) {
      if (!again.deduped) round.problem(`key for ${again.id} created a second job during compaction`);
    }
  }
  await running;

  round.dumpLedger();
  const view = round.dumpLog();
  if (view) round.say(`final generation ${view.header.generation}`);
  queue.close();

  const reopened = openQueue(round.queueDir, options);
  for (const { id } of first) {
    if (reopened.getJob(id)?.status !== 'done') round.problem(`job ${id} did not finish`);
  }
  const stats = reopened.stats();
  if (stats.total !== total) round.problem(`expected ${total} jobs, found ${stats.total}`);
  reopened.close();
}

/** Short leases and slow jobs: a live worker must keep its job. */
async function leaseRound(round, random) {
  const queue = openQueue(round.queueDir);
  const total = 8;
  queue.enqueueMany(Array.from({ length: total }, (_, n) => ({ type: 'work', payload: { n, ms: 1_200 + Math.floor(random() * 300) } })));
  await runPool(round, { size: 3, leaseMs: 800, heartbeatMs: 100 });

  const entries = round.dumpLedger();
  round.dumpLog();
  const starts = new Map();
  for (const entry of entries) {
    if (entry.event === 'start') starts.set(entry.id, (starts.get(entry.id) ?? 0) + 1);
  }
  for (const [id, count] of starts) {
    if (count !== 1) round.problem(`job ${id} ran ${count} times while its worker was alive`);
  }
  queue.close();
}

async function main() {
  const { seed, seconds } = parseArgs(process.argv.slice(2));
  const random = makeRandom(seed);
  const deadline = performance.now() + seconds * 1000;
  const kinds = [
    ['contention', contentionRound],
    ['crash', crashRound],
    ['compaction', compactionRound],
    ['lease', leaseRound],
  ];

  console.log(`walq stress: seed ${seed}, about ${seconds}s`);
  const summary = [];
  for (let index = 1; performance.now() < deadline; index += 1) {
    const [name, run] = kinds[(index - 1) % kinds.length];
    const round = new Round(index, name);
    const started = performance.now();
    round.say('starting');
    try {
      await run(round, random);
    } catch (err) {
      round.problem(`${err.name}: ${err.message}`);
    }
    const elapsed = Math.round(performance.now() - started);
    summary.push({ index, name, elapsed, problems: round.problems });
    round.say(`finished in ${elapsed}ms with ${round.problems.length} problem(s)`);
    round.cleanup();
  }

  console.log('\n=== summary ===');
  let bad = 0;
  for (const { index, name, elapsed, problems } of summary) {
    console.log(`round ${index} ${name}: ${elapsed}ms, ${problems.length} problem(s)`);
    for (const problem of problems) console.log(`    ${problem}`);
    bad += problems.length;
  }
  console.log(`${summary.length} rounds, ${bad} problem(s)`);
  process.exit(bad === 0 ? 0 : 1);
}

await main();

