export function buildSnapshot(state, now, config) {
  const kept = new Map();
  for (const job of state.jobs.values()) {
    if (!isPastRetention(job, now, config)) kept.set(job.id, job);
  }

  return {
    t: 'snapshot',
    at: now,
    seq: state.seq,
    completionSeq: state.completionSeq,
    jobs: [...kept.values()].map(serializeJob),
